<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Create lease · LRC LLC</title><style>body{font:15px system-ui;margin:32px;background:#f5f7f8;color:#17212b}main{max-width:760px;margin:auto;background:white;padding:28px;border-radius:14px}label{display:block;margin:14px 0 5px}input,select,textarea{box-sizing:border-box;width:100%;padding:10px;border:1px solid #ccd4da;border-radius:7px}button{margin-top:20px;padding:12px 18px;background:#126e66;color:white;border:0;border-radius:7px}.error{color:#a22}</style></head><body><main><p><a href="{{ route('leases.index') }}">← Leases</a></p><h1>Create lease (draft)</h1><p>Draft leases do not create rent charges. An authorized manager must approve the lease after reviewing the agreement.</p>@if($errors->any())<ul class="error">@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul>@endif<form method="post" action="{{ route('leases.store') }}">@csrf<label>Property</label><select name="property_id" required><option value="">Choose property</option>@foreach($properties as $property)<option value="{{ $property->id }}" @selected(old('property_id')==$property->id)>{{ $property->name }}</option>@endforeach</select><label>Unit</label><select name="property_unit_id" required><option value="">Choose unit</option>@foreach($units as $unit)<option value="{{ $unit->id }}" @selected(old('property_unit_id')==$unit->id)>{{ $unit->property->name }} — {{ $unit->unit_code }}</option>@endforeach</select><label>Tenant</label><select name="tenant_id" required><option value="">Choose tenant</option>@foreach($tenants as $tenant)<option value="{{ $tenant->id }}" @selected(request('tenant_id',old('tenant_id'))==$tenant->id)>{{ $tenant->legal_name }} ({{ $tenant->phone }})</option>@endforeach</select><label>Lease start</label><input type="date" name="starts_on" required value="{{ old('starts_on') }}"><label>Lease end (optional)</label><input type="date" name="ends_on" value="{{ old('ends_on') }}"><label>Monthly rent (RWF)</label><input type="number" min="1" step=".01" name="monthly_rent" required value="{{ old('monthly_rent') }}"><label>Security deposit required (RWF)</label><input type="number" min="0" step=".01" name="security_deposit_required" value="{{ old('security_deposit_required',0) }}"><label>Rent due day (1–28)</label><input type="number" min="1" max="28" name="rent_due_day" required value="{{ old('rent_due_day',1) }}"><label>Special terms</label><textarea name="special_terms">{{ old('special_terms') }}</textarea><button type="submit">Save draft lease</button></form></main></body></html>